export const catalog = new Map(rows.map(([key,...values]) => [key, values]))
export function translate(text: string, language: Language, params?: Record<string,string>): string {
  const trimmed = text.trim()
  const index = languages.findIndex(([code]) => code === language) - 1
  let result = index < 0 ? text : text.replace(trimmed, catalog.get(trimmed)?.[index] || trimmed)
  // Only known interface templates are interpolated; names and content stay intact.
  if (index >= 0 && !catalog.has(trimmed)) {
    for (const [prefix, key, parameter] of [
      ['A moment shared by ', 'A moment shared by {name}', 'name'],
      ['Delete ', 'Delete {title}', 'title'],
    ]) {
      if (trimmed.startsWith(prefix) && trimmed.length > prefix.length) {
        result = text.replace(trimmed, translate(key, language, { [parameter]: trimmed.slice(prefix.length) }))
        break
      }
    }
  }
  for (const [key,value] of Object.entries(params || {})) result = result.replaceAll(`{${key}}`,value)
  return result
}
export function translateError(text: string, language: Language) {
  if (language === 'en' || catalog.has(text.trim())) return translate(text,language)
  // Provider diagnostics stay out of the localized UI, rather than leaking English.
  return translate('Something went wrong. Please try again.',language)
}
// Localize the existing React view without touching event handlers, input values,
// identity, recording or data. Opaque user-authored regions opt out explicitly.
export function localizeView(node: ReactNode, language: Language): ReactNode {
  if (typeof node === 'string') return translate(node,language)
  if (Array.isArray(node)) return node.map(child => localizeView(child,language))
  if (!isValidElement<Record<string,unknown>>(node)) return node
  const props = node.props
  if (props.translate === 'no') return node
  const translated: Record<string,unknown> = {}
  for (const attribute of ['placeholder','aria-label','title','alt']) if (typeof props[attribute] === 'string') translated[attribute] = translate(props[attribute] as string,language)
  // Preserve option values when localized labels change.
  if (node.type === 'option' && !props.value && typeof props.children === 'string') translated.value = props.children
  if (props.children !== undefined) translated.children = localizeView(props.children as ReactNode,language)
  return cloneElement(node,translated)
}
